#!/bin/bash
# FILENAME: 1_start.sh
# DESCRIPTION: Ingest the region into its zarr store, build the tissue mask, load QC figures.
# Generated by slurm_scripts/script.py (Anvil). Step bodies follow aws_templates/aws_s3_template/.

#SBATCH -A mcb130189
#SBATCH -p wholenode
#SBATCH -t {T_START}
#SBATCH --nodes=1
#SBATCH --mem=128gb
#SBATCH -J start_{EXP_N}_{REG_N}
#SBATCH -o {LOG_DIR}/1_start_{EXP_N}_{REG_N}.out
#SBATCH -e {LOG_DIR}/1_start_{EXP_N}_{REG_N}.out

module purge
module load modtree/cpu
module list

# Fail fast from here on: any non-zero exit aborts the job, so --dependency=afterok in chain.sh stops
# downstream steps. Module loads above stay non-fatal (not every module exists on every node type).
set -eo pipefail  # no -u: Lmod module functions read unset variables

export PATH="/home/x-aklein2/.pixi/bin:$PATH"
export SLURM_TMPDIR="${{SLURM_TMPDIR:-${{TMPDIR:-/tmp}}}}"
export PIXI_HOME="${{SLURM_TMPDIR}}/pixi_home_${{SLURM_JOB_ID:-$$}}"
export PIXI_CACHE_DIR="${{SLURM_TMPDIR}}/pixi_cache_${{SLURM_JOB_ID:-$$}}"   # per-job, node-local: no sharing between jobs
export RATTLER_CACHE_DIR="$PIXI_CACHE_DIR"
mkdir -p "$PIXI_HOME" "$PIXI_CACHE_DIR" "$RATTLER_CACHE_DIR"

# Run from a copy of SPIDA: edits to the source tree cannot reach a running job.
WORKDIR="${{SLURM_TMPDIR}}/spida_${{SLURM_JOB_ID:-$$}}"
# copy + env + cache are ~30 GB; the node only purges /tmp at the next other user's job start
trap 'cd /; rm -rf "$WORKDIR" "$PIXI_HOME" "$PIXI_CACHE_DIR"' EXIT
rsync -a --delete --exclude '.pixi/envs' "{SPIDA_ROOT}/" "$WORKDIR/"
cd "$WORKDIR"
# download into the local cache; if that fails (e.g. no network), retry from the shared project cache
pixi install --frozen -e preprocessing || \
    PIXI_CACHE_DIR=/anvil/projects/x-mcb130189/aklein/.cache/rattler/cache \
    RATTLER_CACHE_DIR=/anvil/projects/x-mcb130189/aklein/.cache/rattler/cache \
    pixi install --frozen -e preprocessing

# --- Compute ---
echo -e "\nIngesting region {REGION} of experiment {EXPERIMENT}\n"
pixi run --frozen -e preprocessing \
    python -m spida.S.cli --config {CONFIG_PATH} \
    ingest-region \
    --exp {EXPERIMENT} \
    --reg {REGION} \
    {OVERWRITE_ARG}

# TISSUE_RASTER_ARG is --no_raster when another chain of this region writes tissue_mask.tif
# (the store still gets its qc_mask shapes / tissue_mask labels).
echo -e "\nComputing tissue mask - {REG_N} - {EXP_N}\n"
pixi run --frozen -e preprocessing \
    python -m spida.P.cli --config {CONFIG_PATH} \
    tissue-mask \
    --exp {EXPERIMENT} \
    --reg {REGION} \
    --rho_min {TISSUE_RHO_MIN} \
    {TISSUE_RASTER_ARG}{OVERWRITE_ARG} \
    --plot

echo -e "\nGenerating Load QC Figures\n"
pixi run --frozen -e preprocessing \
    python -m spida.site --config {CONFIG_PATH} \
    generate-load-qc-figs \
    --exp {EXPERIMENT} \
    --reg {REGION} \
    --brain-region {BR} \
    --lab salk {NAMING_MAP_ARG}

echo -e "\nGenerating default Segmentation QC figures\n"
pixi run --frozen -e preprocessing \
    python -m spida.site --config {CONFIG_PATH} \
    generate-seg-qc-figs \
    default \
    --exp {EXPERIMENT} \
    --reg {REGION} \
    --brain-region {BR} \
    --lab salk {NAMING_MAP_ARG}
